// Lua script run via EVALSHA -- Redis executes this atomically, closing the race window
const string ConsumeScript = @"
    local status = redis.call('HGET', KEYS[1], 'status')
    if status == false then return 'invalid'
    elseif status == 'rotated' then return 'reuse'
    else redis.call('HSET', KEYS[1], 'status', 'rotated'); return 'ok'
    end";

public async Task<Result<TokenPair>> RefreshAsync(string presentedToken)
{
    var key = $"refresh:{Hash(presentedToken)}";
    var familyId = (string)await _redis.HashGetAsync(key, "familyId");
    if (familyId is null) return Result<TokenPair>.Fail("invalid_token");

    var outcome = (string)await _redis.ScriptEvaluateAsync(ConsumeScript, new RedisKey[] { key });

    if (outcome == "reuse")
    {
        // theft signal: kill every token in this lineage, not just the one presented
        await _redis.SetAddAsync("revoked-families", familyId);
        await _redis.KeyExpireAsync("revoked-families", TimeSpan.FromMinutes(15)); // matches access-token TTL
        return Result<TokenPair>.Fail("reuse_detected", forceReauth: true);
    }
    if (outcome != "ok") return Result<TokenPair>.Fail("invalid_token");

    var next = _tokenFactory.CreateRefreshToken(familyId, userId: GetUserId(key));
    await _redis.HashSetAsync($"refresh:{Hash(next.Value)}",
        new HashEntry[] { new("familyId", familyId), new("status", "active") });
    await _redis.KeyExpireAsync($"refresh:{Hash(next.Value)}", next.Lifetime);

    return Result<TokenPair>.Ok(new TokenPair(_tokenFactory.CreateAccessToken(GetUserId(key)), next.Value));
}

// gateway middleware -- runs in front of every downstream service, on every request
