public static string ReverseString(string input)
{
    var chars = input.ToCharArray();
    int left = 0, right = chars.Length - 1;

    while (left < right)
    {
        (chars[left], chars[right]) = (chars[right], chars[left]);
        left++;
        right--;
    }

    return new string(chars);
}

public static bool IsPalindrome(string input)
{
    int left = 0, right = input.Length - 1;

    while (left < right)
    {
        if (!char.IsLetterOrDigit(input[left])) { left++; continue; }
        if (!char.IsLetterOrDigit(input[right])) { right--; continue; }

        if (char.ToLowerInvariant(input[left]) != char.ToLowerInvariant(input[right]))
            return false;

        left++;
        right--;
    }

    return true;
}

public static Dictionary<char, int> CountFrequencies(string input)
{
    var counts = new Dictionary<char, int>();

    foreach (var c in input)
    {
        counts[c] = counts.GetValueOrDefault(c) + 1;
    }

    return counts;
}

public static int FirstNonRepeatingIndex(string input)
{
    var counts = new Dictionary<char, int>();
    foreach (var c in input)
        counts[c] = counts.GetValueOrDefault(c) + 1;

    for (int i = 0; i < input.Length; i++)
    {
        if (counts[input[i]] == 1) return i;
    }

    return -1;
}

public static bool HasDuplicate(int[] nums)
{
    var seen = new HashSet<int>();

    foreach (var n in nums)
    {
        if (!seen.Add(n)) return true; // Add returns false if the value already existed
    }

    return false;
}

public static int[] TwoSum(int[] nums, int target)
{
    var seenIndexByValue = new Dictionary<int, int>();

    for (int i = 0; i < nums.Length; i++)
    {
        int complement = target - nums[i];
        if (seenIndexByValue.TryGetValue(complement, out int j))
            return new[] { j, i };

        seenIndexByValue[nums[i]] = i;
    }

    throw new InvalidOperationException("No two sum solution exists.");
}

public static List<(int Start, int End)> MergeIntervals(List<(int Start, int End)> intervals)
{
    if (intervals.Count == 0) return intervals;

    var sorted = intervals.OrderBy(i => i.Start).ToList();
    var merged = new List<(int Start, int End)> { sorted[0] };

    for (int i = 1; i < sorted.Count; i++)
    {
        var last = merged[^1];
        var current = sorted[i];

        if (current.Start <= last.End)
            merged[^1] = (last.Start, Math.Max(last.End, current.End));
        else
            merged.Add(current);
    }

    return merged;
}

public static int[] MergeSorted(int[] a, int[] b)
{
    int i = 0, j = 0, k = 0;
    var result = new int[a.Length + b.Length];

    while (i < a.Length && j < b.Length)
        result[k++] = a[i] <= b[j] ? a[i++] : b[j++];

    while (i < a.Length) result[k++] = a[i++];
    while (j < b.Length) result[k++] = b[j++];

    return result;
}

public static int BinarySearch(int[] sorted, int target)
{
    int low = 0, high = sorted.Length - 1;

    while (low <= high)
    {
        int mid = low + (high - low) / 2;

        if (sorted[mid] == target) return mid;
        if (sorted[mid] < target) low = mid + 1;
        else high = mid - 1;
    }

    return -1;
}

public static int MaxSubarraySum(int[] nums, int k)
{
    int windowSum = 0;
    for (int i = 0; i < k; i++) windowSum += nums[i];

    int maxSum = windowSum;

    for (int i = k; i < nums.Length; i++)
    {
        windowSum += nums[i] - nums[i - k];
        maxSum = Math.Max(maxSum, windowSum);
    }

    return maxSum;
}

public class MinStack
{
    private readonly Stack<int> _values = new();
    private readonly Stack<int> _mins = new();

    public void Push(int value)
    {
        _values.Push(value);
        _mins.Push(_mins.Count == 0 ? value : Math.Min(value, _mins.Peek()));
    }

    public void Pop()
    {
        _values.Pop();
        _mins.Pop();
    }

    public int Top() => _values.Peek();

    public int GetMin() => _mins.Peek();
}

public static bool IsValid(string s)
{
    var pairs = new Dictionary<char, char> { [')'] = '(', [']'] = '[', ['}'] = '{' };
    var stack = new Stack<char>();

    foreach (var c in s)
    {
        if (c == '(' || c == '[' || c == '{')
        {
            stack.Push(c);
        }
        else
        {
            if (stack.Count == 0 || stack.Pop() != pairs[c]) return false;
        }
    }

    return stack.Count == 0;
}

public class ListNode
{
    public int Value;
    public ListNode? Next;
    public ListNode(int value) => Value = value;
}

public static ListNode? Reverse(ListNode? head)
{
    ListNode? prev = null;
    var current = head;

    while (current != null)
    {
        var next = current.Next;
        current.Next = prev;
        prev = current;
        current = next;
    }

    return prev;
}

