{
    public int Value;
    public TreeNode? Left;
    public TreeNode? Right;
    public TreeNode(int value) => Value = value;
}

public static List<int> InOrderIterative(TreeNode? root)
{
    var result = new List<int>();
    var stack = new Stack<TreeNode>();
    var current = root;

    while (current != null || stack.Count > 0)
    {
        while (current != null)
        {
            stack.Push(current);
            current = current.Left;
        }

        current = stack.Pop();
        result.Add(current.Value);
        current = current.Right;
    }

    return result;
}

public static List<int> Bfs(Dictionary<int, List<int>> graph, int start)
{
    var visited = new HashSet<int> { start };
    var order = new List<int>();
    var queue = new Queue<int>();
    queue.Enqueue(start);

    while (queue.Count > 0)
    {
        var node = queue.Dequeue();
        order.Add(node);

        foreach (var neighbor in graph.GetValueOrDefault(node, new List<int>()))
        {
            if (visited.Add(neighbor)) queue.Enqueue(neighbor);
        }
    }

    return order;
}

public static List<int> Dfs(Dictionary<int, List<int>> graph, int start)
{
    var visited = new HashSet<int>();
    var order = new List<int>();
    var stack = new Stack<int>();
    stack.Push(start);

    while (stack.Count > 0)
    {
        var node = stack.Pop();
        if (!visited.Add(node)) continue;

        order.Add(node);

        foreach (var neighbor in graph.GetValueOrDefault(node, new List<int>()))
        {
            if (!visited.Contains(neighbor)) stack.Push(neighbor);
        }
    }

    return order;
}

public static long FibonacciMemo(int n, Dictionary<int, long>? cache = null)
{
    cache ??= new Dictionary<int, long>();
    if (n <= 1) return n;
    if (cache.TryGetValue(n, out var cached)) return cached;

    var result = FibonacciMemo(n - 1, cache) + FibonacciMemo(n - 2, cache);
    cache[n] = result;
    return result;
}

public static int[] MergeSort(int[] nums)
{
    if (nums.Length <= 1) return nums;

    int mid = nums.Length / 2;
    var left = MergeSort(nums[..mid]);
    var right = MergeSort(nums[mid..]);

    return Merge(left, right);
}

private static int[] Merge(int[] left, int[] right)
{
    var result = new int[left.Length + right.Length];
    int i = 0, j = 0, k = 0;

    while (i < left.Length && j < right.Length)
        result[k++] = left[i] <= right[j] ? left[i++] : right[j++];

    while (i < left.Length) result[k++] = left[i++];
    while (j < right.Length) result[k++] = right[j++];

    return result;
}

public class LruCache<TKey, TValue> where TKey : notnull
{
    private readonly int _capacity;
    private readonly Dictionary<TKey, LinkedListNode<(TKey Key, TValue Value)>> _map;
    private readonly LinkedList<(TKey Key, TValue Value)> _order = new();

    public LruCache(int capacity)
    {
        _capacity = capacity;
        _map = new Dictionary<TKey, LinkedListNode<(TKey, TValue)>>(capacity);
    }

    public bool TryGet(TKey key, out TValue value)
    {
        if (_map.TryGetValue(key, out var node))
        {
            _order.Remove(node);
            _order.AddFirst(node);
            value = node.Value.Value;
            return true;
        }

        value = default!;
        return false;
    }

    public void Put(TKey key, TValue value)
    {
        if (_map.TryGetValue(key, out var existing))
        {
            _order.Remove(existing);
        }
        else if (_map.Count >= _capacity)
        {
            var lru = _order.Last!;
            _order.RemoveLast();
            _map.Remove(lru.Value.Key);
        }

        var node = new LinkedListNode<(TKey, TValue)>((key, value));
        _order.AddFirst(node);
        _map[key] = node;
    }
}

public class TokenBucketRateLimiter
{
    private readonly int _capacity;
    private readonly double _refillTokensPerSecond;
    private readonly object _lock = new();
    private double _tokens;
    private DateTime _lastRefill;

    public TokenBucketRateLimiter(int capacity, double refillTokensPerSecond)
    {
        _capacity = capacity;
        _refillTokensPerSecond = refillTokensPerSecond;
        _tokens = capacity;
        _lastRefill = DateTime.UtcNow;
    }

    public bool TryAcquire()
    {
        lock (_lock)
        {
            Refill();
            if (_tokens < 1) return false;
            _tokens -= 1;
            return true;
        }
    }

    private void Refill()
    {
        var now = DateTime.UtcNow;
        var elapsedSeconds = (now - _lastRefill).TotalSeconds;
        _tokens = Math.Min(_capacity, _tokens + elapsedSeconds * _refillTokensPerSecond);
        _lastRefill = now;
    }
}

public static async Task<T> RetryWithBackoffAsync<T>(
    Func<Task<T>> operation,
    int maxAttempts = 5,
    TimeSpan? baseDelay = null)
{
    var delay = baseDelay ?? TimeSpan.FromMilliseconds(200);
    var random = new Random();

    for (int attempt = 1; attempt <= maxAttempts; attempt++)
    {
        try
        {
            return await operation();
        }
        catch when (attempt < maxAttempts)
        {
            var exponential = delay.TotalMilliseconds * Math.Pow(2, attempt - 1);
            var jitter = random.NextDouble() * exponential * 0.25;
            await Task.Delay(TimeSpan.FromMilliseconds(exponential + jitter));
        }
    }

    // Unreachable: the final attempt (attempt == maxAttempts) is not caught above,
    // so a real failure propagates out of the loop instead of falling through here.
    throw new InvalidOperationException("Unreachable");
}

