public class ProducerConsumerPipeline<T>
{
    private readonly BlockingCollection<T> _queue;

    public ProducerConsumerPipeline(int boundedCapacity) =>
        _queue = new BlockingCollection<T>(boundedCapacity);

    public void Produce(T item) => _queue.Add(item); // blocks if the queue is full

    public void CompleteProducing() => _queue.CompleteAdding();

    public void Consume(Action<T> process)
    {
        // Blocks when empty; exits cleanly once CompleteAdding() is called and the queue drains.
        foreach (var item in _queue.GetConsumingEnumerable())
        {
            process(item);
        }
    }
}

public class BoundedBlockingQueue<T>
{
    private readonly Queue<T> _items = new();
    private readonly int _capacity;
    private readonly object _lock = new();

    public BoundedBlockingQueue(int capacity) => _capacity = capacity;

    public void Enqueue(T item)
    {
        lock (_lock)
        {
            while (_items.Count >= _capacity)
                Monitor.Wait(_lock);

            _items.Enqueue(item);
            Monitor.PulseAll(_lock);
        }
    }

    public T Dequeue()
    {
        lock (_lock)
        {
            while (_items.Count == 0)
                Monitor.Wait(_lock);

            var item = _items.Dequeue();
            Monitor.PulseAll(_lock);
            return item;
        }
    }
}

public class TtlCache<TKey, TValue> where TKey : notnull
{
    private class Entry
    {
        public required TValue Value { get; init; }
        public required DateTime ExpiresAt { get; init; }
    }

    private readonly ConcurrentDictionary<TKey, Entry> _entries = new();
    private readonly TimeSpan _ttl;

    public TtlCache(TimeSpan ttl) => _ttl = ttl;

    public void Set(TKey key, TValue value) =>
        _entries[key] = new Entry { Value = value, ExpiresAt = DateTime.UtcNow + _ttl };

    public bool TryGet(TKey key, out TValue value)
    {
        if (_entries.TryGetValue(key, out var entry))
        {
            if (entry.ExpiresAt > DateTime.UtcNow)
            {
                value = entry.Value;
                return true;
            }

            _entries.TryRemove(key, out _); // lazily evict on access
        }

        value = default!;
        return false;
    }
}

public class SimpleContainer
{
    private readonly Dictionary<Type, Type> _registrations = new();

    public void Register<TService, TImplementation>() where TImplementation : TService =>
        _registrations[typeof(TService)] = typeof(TImplementation);

    public object Resolve(Type serviceType)
    {
        var implementationType = _registrations.GetValueOrDefault(serviceType, serviceType);
        var constructor = implementationType.GetConstructors().First();

        var parameters = constructor.GetParameters()
            .Select(p => Resolve(p.ParameterType))
            .ToArray();

        return Activator.CreateInstance(implementationType, parameters)!;
    }

    public T Resolve<T>() => (T)Resolve(typeof(T));
}

