public class HttpContextLite
{
    public required string Path { get; init; }
    public int StatusCode { get; set; } = 200;
}

public class MiddlewarePipelineBuilder
{
    private readonly List<Func<RequestDelegate, RequestDelegate>> _components = new();

    public MiddlewarePipelineBuilder Use(Func<HttpContextLite, Func<Task>, Task> middleware)
    {
        _components.Add(next => context => middleware(context, () => next(context)));
        return this;
    }

    public RequestDelegate Build(RequestDelegate terminal)
    {
        var pipeline = terminal;

        for (int i = _components.Count - 1; i >= 0; i--)
        {
            pipeline = _components[i](pipeline);
        }

        return pipeline;
    }
}

public class PagedResult<T>
{
    public required List<T> Items { get; init; }
    public required int TotalCount { get; init; }
    public required int PageNumber { get; init; }
    public required int PageSize { get; init; }
    public int TotalPages => (int)Math.Ceiling(TotalCount / (double)PageSize);
}

public static class PaginationExtensions
{
    public static PagedResult<T> ToPagedResult<T>(this IQueryable<T> query, int pageNumber, int pageSize)
    {
        var totalCount = query.Count(); // translated to a SQL COUNT, not an in-memory count

        var items = query
            .Skip((pageNumber - 1) * pageSize)
            .Take(pageSize)
            .ToList(); // executes now — only this page's rows are pulled

        return new PagedResult<T>
        {
            Items = items,
            TotalCount = totalCount,
            PageNumber = pageNumber,
            PageSize = pageSize
        };
    }
}

public static List<string> ParseCsvLine(string line)
{
    var fields = new List<string>();
    var current = new StringBuilder();
    bool inQuotes = false;

    for (int i = 0; i < line.Length; i++)
    {
        char c = line[i];

        if (inQuotes)
        {
            if (c == '"' && i + 1 < line.Length && line[i + 1] == '"')
            {
                current.Append('"');
                i++; // skip the escaped quote's second character
            }
            else if (c == '"')
            {
                inQuotes = false;
            }
            else
            {
                current.Append(c);
            }
        }
        else
        {
            if (c == '"') inQuotes = true;
            else if (c == ',') { fields.Add(current.ToString()); current.Clear(); }
            else current.Append(c);
        }
    }

    fields.Add(current.ToString());
    return fields;
}

public static Dictionary<(DateTime Hour, string Level), int> AggregateByHourAndLevel(IEnumerable<string> logLines)
{
    var counts = new Dictionary<(DateTime, string), int>();

    foreach (var line in logLines) // streams one line at a time — never materializes the whole file
    {
        var parts = line.Split(' ', 3);
        if (parts.Length < 2) continue;

        if (!DateTime.TryParse(parts[0], null, DateTimeStyles.AdjustToUniversal, out var timestamp))
            continue;

        var hourBucket = new DateTime(timestamp.Year, timestamp.Month, timestamp.Day, timestamp.Hour, 0, 0, DateTimeKind.Utc);
        var level = parts[1];
        var key = (hourBucket, level);

        counts[key] = counts.GetValueOrDefault(key) + 1;
    }

    return counts;
}

public class UrlShortener
{
    private const string Base62Chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    private readonly Dictionary<long, string> _idToUrl = new();
    private long _nextId = 1;

    public string Shorten(string longUrl)
    {
        long id = _nextId++;
        _idToUrl[id] = longUrl;
        return Encode(id);
    }

    public string? Resolve(string shortCode)
    {
        var id = Decode(shortCode);
        return _idToUrl.GetValueOrDefault(id);
    }

    private static string Encode(long id)
    {
        if (id == 0) return Base62Chars[0].ToString();

        var sb = new StringBuilder();
        while (id > 0)
        {
            sb.Insert(0, Base62Chars[(int)(id % 62)]);
            id /= 62;
        }
        return sb.ToString();
    }

    private static long Decode(string code)
    {
        long id = 0;
        foreach (var c in code)
        {
            id = id * 62 + Base62Chars.IndexOf(c);
        }
        return id;
    }
}
